export interface ConnectorConfig {
  hubspotAccessToken: string
  fetch?: typeof fetch
}

export interface StripeCheckoutSessionCompletedPayload {
  id: string
  object: string
  customer_email?: string
  customer?: string | { email?: string }
  amount_total?: number
  currency?: string
  payment_status?: string
  status?: string
  created?: number
  livemode?: boolean
}

export interface HubSpotContactResult {
  vid: number
  isNew: boolean
  hubspotContactEmail: string
  stripeSessionId: string
}

function getCustomerEmail(payload: StripeCheckoutSessionCompletedPayload): string | undefined {
  if (payload.customer_email) return payload.customer_email
  if (typeof payload.customer === 'object' && payload.customer?.email) return payload.customer.email
  return undefined
}

export async function handle(
  payload: StripeCheckoutSessionCompletedPayload,
  config: ConnectorConfig
): Promise<HubSpotContactResult> {
  if (!payload.id) throw new Error('Missing required field: id (Stripe session ID)')
  if (payload.object !== 'checkout.session') {
    throw new Error(`Invalid object type: expected 'checkout.session', got '${payload.object}'`)
  }

  const email = getCustomerEmail(payload)
  if (!email) throw new Error('Missing required field: customer_email (or customer.email)')

  const fetchImpl = config.fetch ?? fetch
  const url = `https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/${encodeURIComponent(email)}`
  const body = JSON.stringify({
    properties: [{ property: 'email', value: email }]
  })

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.hubspotAccessToken}`,
      'Content-Type': 'application/json',
      'Idempotency-Key': payload.id
    },
    body
  })

  if (!response.ok) {
    throw new Error(`HubSpot API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const result = await response.json() as HubSpotContactResult
  return {
    vid: result.vid,
    isNew: result.isNew,
    hubspotContactEmail: email,
    stripeSessionId: payload.id
  }
}

