    expect(result.hubspotContactEmail).toBe('customer@example.com')
    expect(result.stripeSessionId).toBe(SOURCE_EXAMPLE.id)
  })
})

describe('handle', () => {
  it('happy path: creates/updates HubSpot contact with correct request', async () => {
