      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/customer%40example.com')
      expect(req.headers.get('authorization')).toBe('Bearer test-token')
      expect(req.headers.get('idempotency-key')).toBe('cs_test_123')
      expect(req.json).toEqual({ properties: [{ property: 'email', value: 'customer@example.com' }] })
      return jsonResponse({ vid: 98765, isNew: true })
    })

    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_test_123',
      object: 'checkout.session',
      customer_email: 'customer@example.com'
    }

    const result = await handle(payload, { hubspotAccessToken: 'test-token', fetch })
    expect(result).toEqual({
      vid: 98765,
      isNew: true,
      hubspotContactEmail: 'customer@example.com',
      stripeSessionId: 'cs_test_123'
    })
    expect(calls.length).toBe(1)
  })

  it('uses customer.email when customer_email is missing', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.url).toBe('https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/nested%40example.com')
      return jsonResponse({ vid: 111, isNew: false })
    })

    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_nested',
      object: 'checkout.session',
      customer: { email: 'nested@example.com' }
    }

    const result = await handle(payload, { hubspotAccessToken: 'token', fetch })
    expect(result.hubspotContactEmail).toBe('nested@example.com')
    expect(calls.length).toBe(1)
  })

  it('throws when id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { object: 'checkout.session', customer_email: 'test@example.com' } as StripeCheckoutSessionCompletedPayload
    await expect(handle(payload, { hubspotAccessToken: 'token', fetch })).rejects.toThrow('Missing required field: id')
  })

  it('throws when object is not checkout.session', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_123',
      object: 'checkout.session.expired',
      customer_email: 'test@example.com'
    }
    await expect(handle(payload, { hubspotAccessToken: 'token', fetch })).rejects.toThrow("Invalid object type")
  })

  it('throws when customer_email and customer.email are both missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_123',
      object: 'checkout.session',
      customer: 'cus_123'
    }
    await expect(handle(payload, { hubspotAccessToken: 'token', fetch })).rejects.toThrow('Missing required field: customer_email')
  })

  it('throws on non-2xx HubSpot response with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401))
    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_123',
      object: 'checkout.session',
      customer_email: 'test@example.com'
    }
    await expect(handle(payload, { hubspotAccessToken: 'bad-token', fetch })).rejects.toThrow(
      'HubSpot API error: 401 Unauthorized for POST https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/test%40example.com'
    )
    expect(calls.length).toBe(1)
  })

  it('throws on 500 HubSpot response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'server error' }, 500))
    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_123',
      object: 'checkout.session',
      customer_email: 'test@example.com'
    }
    await expect(handle(payload, { hubspotAccessToken: 'token', fetch })).rejects.toThrow(
      'HubSpot API error: 500 Internal Server Error for POST https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/test%40example.com'
    )
  })
})

